class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        if s1 == s2:
            return True
        if sorted(s1) != sorted(s2):
            return False
        n = len(s1)
        for cut in range(1, n):
            if self.isScramble(s1[:cut], s2[:cut]) and self.isScramble(s1[cut:], s2[cut:]):
                return True
            if self.isScramble(s1[:cut], s2[n - cut:]) and self.isScramble(s1[cut:], s2[:n - cut]):
                return True
        return False

solutions.better:
class Solution:
    def isScramble(self, s1, s2):
        from functools import lru_cache
        @lru_cache(None)
        def dfs(a, b):
            if a == b:
                return True
            if sorted(a) != sorted(b):
                return False
            n = len(a)
            for cut in range(1, n):
                if dfs(a[:cut], b[:cut]) and dfs(a[cut:], b[cut:]):
                    return True
                if dfs(a[:cut], b[n - cut:]) and dfs(a[cut:], b[:n - cut]):
                    return True
            return False
        return dfs(s1, s2)

